{
  "name": "claude-animation-base",
  "version": "1.0.0",
  "private": true,
  "license": "MIT",
  "description": "Clawd, painted in p5.brush: a character kit and guide for making hand-painted Clawd animations",
  "scripts": {
    "sheet": "node render.mjs --sheet=0,1,2,3,4,5 --out=out/sheet.jpg",
    "video": "node render.mjs --clip --out=out/video.mp4"
  },
  "dependencies": {
    "p5": "^2.3.3",
    "p5.brush": "^2.2.3",
    "puppeteer-core": "^25.11.0"
  }
}

{
  "name": "line-art-animation",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "A Claude skill and small TypeScript library for animated line-art SVG components.",
  "license": "MIT",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "typecheck": "tsc -p tsconfig.json && tsc -p examples/village/tsconfig.json",
    "capture": "node scripts/capture.ts"
  },
  "devDependencies": {
    "@types/node": "^22.18.0",
    "typescript": "^5.9.3",
    "vite": "^7.1.9"
  }
}

{
  "name": "@motlab/cli",
  "version": "0.4.1",
  "description": "Video as code: canvas scene pages rendered frame by frame in headless Chrome with WebCodecs, a project format with audio, a web viewer, and an agent skill that builds the scenes.",
  "license": "MIT OR Apache-2.0",
  "author": "StaryOne",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/staryone/motlab.git"
  },
  "homepage": "https://github.com/staryone/motlab#readme",
  "bugs": {
    "url": "https://github.com/staryone/motlab/issues"
  },
  "keywords": [
    "video",
    "motion-graphics",
    "canvas",
    "webcodecs",
    "headless-chrome",
    "agent-skills",
    "claude-code"
  ],
  "type": "module",
  "engines": {
    "node": ">=24"
  },
  "bin": {
    "motlab": "bin/motlab.js"
  },
  "files": [
    "bin/",
    "src/",
    "skills/",
    "example/",
    "!example/out/",
    "!example/selection.json",
    "!example/selection/",
    "docs/",
    "install.js",
    "CHANGELOG.md",
    "LICENSE-MIT",
    "LICENSE-APACHE",
    "THIRD_PARTY_NOTICES.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test": "node --test",
    "doctor": "node bin/motlab.js doctor"
  },
  "dependencies": {
    "mediabunny": "1.66.0"
  }
}
